#!/usr/bin/env python3
"""
Automatisk generert av generate.py (perfmobile) - IKKE rediger denne filen direkte.

Ytelsesfiks (listGroups filtrerer nå faktisk, availability-ruten starter alle
uavhengige oppslag samtidig) + mobil-rekkefolge (Dagens avtaler over Oversikt).

Legger OGSA igjen en ny fil, supabase/migrations/0005_add_booking_slots_index.sql
- den kjores IKKE av dette skriptet (det er bare SQL), men MA limes inn og
kjores i Supabase sitt SQL Editor separat, se utskriften til slutt.

Idempotent: hvert steg hopper over seg selv hvis allerede gjort.
Kjor fra prosjektroten: python3 scripts/deploy_perf_and_mobile.py
"""
import pathlib
import subprocess
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent

ok = True

def apply_edit(path, old, new, marker, label):
    global ok
    text = path.read_text()
    if marker in text:
        print(f"[already done] {label}")
        return
    if text.count(old) != 1:
        print(f"[SKIPPED - ikke funnet/entydig] {label}")
        ok = False
        return
    path.write_text(text.replace(old, new, 1))
    print(f"[OK] {label}")

def write_full(path, content, marker, label):
    global ok
    if path.exists() and marker in path.read_text():
        print(f"[already done] {label}")
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content)
    print(f"[OK] {label}")

SB_PATH = ROOT / 'lib' / 'db' / 'supabase.ts'
apply_edit(SB_PATH, 'import { COURT_ID } from "@/lib/config";', 'import { addDays } from "date-fns";\nimport { fromZonedTime } from "date-fns-tz";\nimport { COURT_ID, TIME_ZONE } from "@/lib/config";', 'from "date-fns-tz"', 'sb-import')
apply_edit(SB_PATH, '  async listGroups(_filter: ListGroupsFilter) {\n    const supabase = getSupabaseAdmin();\n\n    const [{ data: groupRows, error: groupError }, { data: slotRows, error: slotError }] = await Promise.all([\n      supabase.from("booking_groups").select("*"),\n      supabase.from("booking_slots").select("*"),\n    ]);\n\n    if (groupError) throw new Error(`Kunne ikke hente bookinger: ${groupError.message}`);\n    if (slotError) throw new Error(`Kunne ikke hente tidsluker: ${slotError.message}`);\n\n    const slots = ((slotRows as SlotRow[] | null) ?? []).map(mapSlot);\n\n    return ((groupRows as GroupRow[] | null) ?? [])\n      .map(mapGroup)\n      .map((group) => ({ ...group, slots: slots.filter((s) => s.groupId === group.id) }))\n      .sort((a, b) => {\n        const aStart = a.slots[0]?.startTime ?? a.createdAt;\n        const bStart = b.slots[0]?.startTime ?? b.createdAt;\n        return aStart.localeCompare(bStart);\n      });\n  },', '  async listGroups(filter: ListGroupsFilter) {\n    const supabase = getSupabaseAdmin();\n\n    // Begrenser hvor mye som faktisk hentes til et vindu rundt dagens dato\n    // (se app/api/admin/bookings/route.ts, som alltid sender fromDate/\n    // toDate) i stedet for ALT noensinne booket. Parameteret het tidligere\n    // "_filter" MED VILJE (for å markere at det ikke ble brukt) og ble\n    // fullstendig ignorert – adminpanelet hentet derfor hele\n    // bookingshistorikken på HVERT eneste kall, og ble tregere og tregere jo\n    // lenger klubben hadde brukt systemet. fromDate/toDate tolkes som lokale\n    // (klubbens tidssone) kalenderdatoer, akkurat som "hele dagen"-\n    // blokkeringer i app/api/admin/block/route.ts.\n    let relevantGroupIds: string[] | null = null;\n    if (filter.fromDate || filter.toDate) {\n      let idsQuery = supabase.from("booking_slots").select("group_id");\n      if (filter.fromDate) {\n        idsQuery = idsQuery.gte("start_time", fromZonedTime(`${filter.fromDate}T00:00:00`, TIME_ZONE).toISOString());\n      }\n      if (filter.toDate) {\n        const exclusiveEnd = addDays(fromZonedTime(`${filter.toDate}T00:00:00`, TIME_ZONE), 1);\n        idsQuery = idsQuery.lt("start_time", exclusiveEnd.toISOString());\n      }\n      const { data: idRows, error: idError } = await idsQuery;\n      if (idError) throw new Error(`Kunne ikke hente bookinger: ${idError.message}`);\n      relevantGroupIds = Array.from(new Set((idRows ?? []).map((r) => r.group_id as string)));\n      if (relevantGroupIds.length === 0) return [];\n    }\n\n    let groupsQuery = supabase.from("booking_groups").select("*");\n    let slotsQuery = supabase.from("booking_slots").select("*");\n    if (relevantGroupIds) {\n      groupsQuery = groupsQuery.in("id", relevantGroupIds);\n      slotsQuery = slotsQuery.in("group_id", relevantGroupIds);\n    }\n\n    const [{ data: groupRows, error: groupError }, { data: slotRows, error: slotError }] = await Promise.all([\n      groupsQuery,\n      slotsQuery,\n    ]);\n\n    if (groupError) throw new Error(`Kunne ikke hente bookinger: ${groupError.message}`);\n    if (slotError) throw new Error(`Kunne ikke hente tidsluker: ${slotError.message}`);\n\n    const slots = ((slotRows as SlotRow[] | null) ?? []).map(mapSlot);\n\n    return ((groupRows as GroupRow[] | null) ?? [])\n      .map(mapGroup)\n      .map((group) => ({ ...group, slots: slots.filter((s) => s.groupId === group.id) }))\n      .sort((a, b) => {\n        const aStart = a.slots[0]?.startTime ?? a.createdAt;\n        const bStart = b.slots[0]?.startTime ?? b.createdAt;\n        return aStart.localeCompare(bStart);\n      });\n  },', 'relevantGroupIds: string[] | null', 'sb-listgroups')

AB_PATH = ROOT / 'app' / 'api' / 'admin' / 'bookings' / 'route.ts'
apply_edit(AB_PATH, 'import { NextResponse } from "next/server";\nimport { getRepository } from "@/lib/db";\nimport { expireStaleHolds } from "@/lib/holds";\n\nexport const dynamic = "force-dynamic";\n\n/**\n * GET /api/admin/bookings\n *\n * Lister alle bookinger (uansett status), til bruk i adminpanelet. Beskyttet\n * av middleware.ts – krever innlogget admin.\n *\n * Sortert etter NÅR BOOKINGEN BLE OPPRETTET (nyeste øverst) – IKKE etter\n * hvilket klokkeslett som ble booket. repo.listGroups() sin egen rekkefølge\n * (etter øktens tidspunkt) er riktig for andre bruk (f.eks. dagens avtaler i\n * BookingsInsights.tsx), så omsorteringen skjer her, kun for dette\n * endepunktet – se app/admin/AdminDashboard.tsx sin "Siste bookinger".\n */\nexport async function GET() {\n  try {\n    await expireStaleHolds();\n  } catch (err) {\n    console.error("[admin/bookings] kunne ikke rydde opp utløpte holds:", err);\n  }\n\n  const repo = await getRepository();\n  const groups = await repo.listGroups({});\n  const sorted = [...groups].sort((a, b) => b.createdAt.localeCompare(a.createdAt));', 'import { NextResponse } from "next/server";\nimport { getRepository } from "@/lib/db";\nimport { expireStaleHolds } from "@/lib/holds";\nimport { MAX_RECURRING_WEEKS } from "@/lib/config";\nimport { todayInClubTimeZone } from "@/lib/slots";\n\nexport const dynamic = "force-dynamic";\n\n/** Hvor mange dager BAKOVER i tid "Siste bookinger" (se app/admin/AdminDashboard.tsx) fortsatt viser historikk for – romslig (et halvt år), men IKKE ubegrenset. Se begrunnelsen i lib/db/supabase.ts sin listGroups. */\nconst HISTORY_DAYS_BACK = 180;\n\n/** Litt margin FORBI MAX_RECURRING_WEEKS – sikrer at ALLE forekomster i den lengste mulig gjentakende rekken fortsatt kommer med, selv om den akkurat treffer kanten av vinduet. */\nconst FUTURE_MARGIN_DAYS = 7;\n\n/** Flytter en "YYYY-MM-DD"-dato et gitt antall dager – ren UTC-millisekund-aritmetikk med vilje (ikke date-fns\' addDays, som bruker VERTENS lokale tidssone), slik at dette blir riktig uansett hvilken tidssone serveren/maskinen kjører i. Samme mønster som generateWeeklyDates i lib/slots.ts. */\nfunction shiftDateString(dateStr: string, days: number): string {\n  const [y, m, d] = dateStr.split("-").map(Number);\n  const shifted = new Date(Date.UTC(y, m - 1, d) + days * 86_400_000);\n  const pad = (n: number) => n.toString().padStart(2, "0");\n  return `${shifted.getUTCFullYear()}-${pad(shifted.getUTCMonth() + 1)}-${pad(shifted.getUTCDate())}`;\n}\n\n/**\n * GET /api/admin/bookings\n *\n * Lister bookinger innenfor et vindu rundt dagens dato (se HISTORY_DAYS_BACK/\n * FUTURE_MARGIN_DAYS over) – IKKE lenger ALT noensinne booket, se\n * begrunnelsen i lib/db/supabase.ts sin listGroups. Beskyttet av\n * middleware.ts – krever innlogget admin.\n *\n * Sortert etter NÅR BOOKINGEN BLE OPPRETTET (nyeste øverst) – IKKE etter\n * hvilket klokkeslett som ble booket. repo.listGroups() sin egen rekkefølge\n * (etter øktens tidspunkt) er riktig for andre bruk (f.eks. dagens avtaler i\n * BookingsInsights.tsx), så omsorteringen skjer her, kun for dette\n * endepunktet – se app/admin/AdminDashboard.tsx sin "Siste bookinger".\n */\nexport async function GET() {\n  try {\n    await expireStaleHolds();\n  } catch (err) {\n    console.error("[admin/bookings] kunne ikke rydde opp utløpte holds:", err);\n  }\n\n  const repo = await getRepository();\n  const today = todayInClubTimeZone();\n  const groups = await repo.listGroups({\n    fromDate: shiftDateString(today, -HISTORY_DAYS_BACK),\n    toDate: shiftDateString(today, MAX_RECURRING_WEEKS * 7 + FUTURE_MARGIN_DAYS),\n  });\n  const sorted = [...groups].sort((a, b) => b.createdAt.localeCompare(a.createdAt));', 'function shiftDateString', 'ab-full')

AV_PATH = ROOT / 'app' / 'api' / 'squash' / 'availability' / 'route.ts'
apply_edit(AV_PATH, '  const adminSession = await verifySessionCookieValue(request.cookies.get(SESSION_COOKIE_NAME)?.value);\n  const isFullAdmin = adminSession?.role === "full";\n\n  if (!isFullAdmin) {\n    if (dateStr < todayInClubTimeZone()) {\n      return NextResponse.json({ date: dateStr, slots: [], closed: true, note: null });\n    }\n\n    // VIKTIG: dette er IKKE det samme som at banen er "stengt" denne dagen\n    // – den er fysisk åpen akkurat som vanlig, det er bare ikke lov å booke\n    // en ENKELTTIME så langt frem i tid (ennå). Får derfor sitt EGET flagg\n    // (`tooFarAhead`) i stedet for å late som dagen er stengt, slik at\n    // bookingsiden kan vise en korrekt melding (se BookingCalendar.tsx).\n    const maxDate = await getEffectiveSingleBookingMaxDate();\n    if (maxDate !== null && dateStr > maxDate) {\n      return NextResponse.json({ date: dateStr, slots: [], closed: false, tooFarAhead: true, note: null });\n    }\n  }\n\n  // Starter oppryddingen av utløpte holds SAMTIDIG med åpningstid-oppslaget\n  // under (ikke rett etter) – de to spørringene er helt uavhengige av\n  // hverandre, så å vente ferdig på den ene før den andre i det hele tatt\n  // startet var bare unødvendig ekstra nettverks-ventetid på HVER ENKELT\n  // "hent ledige tider"-forespørsel. Selve databasetriggeren som holder\n  // blocks_time (brukt av findConflicts under) oppdatert kjører likevel i\n  // SAMME transaksjon som denne UPDATE-en, så korrektheten er uendret – vi\n  // sørger bare for at den er ferdig (se `await holdsCleanupPromise` under)\n  // før vi faktisk spør om ledighet. Feil her er ikke kritisk og skal\n  // aldri blokkere eller feile selve svaret, se .catch() under.\n  const holdsCleanupPromise = expireStaleHolds().catch((err) => {\n    console.error("[availability] kunne ikke rydde opp utløpte holds:", err);\n  });\n\n  const hours = await getEffectiveHoursForDate(dateStr);\n  if (hours.closed) {\n    await holdsCleanupPromise;\n    return NextResponse.json({ date: dateStr, slots: [], closed: true, note: hours.note });\n  }\n\n  await holdsCleanupPromise;\n\n  const slots = generateSlotsForDate(dateStr, hours.intervals);', '  const adminSession = await verifySessionCookieValue(request.cookies.get(SESSION_COOKIE_NAME)?.value);\n  const isFullAdmin = adminSession?.role === "full";\n\n  if (!isFullAdmin && dateStr < todayInClubTimeZone()) {\n    return NextResponse.json({ date: dateStr, slots: [], closed: true, note: null });\n  }\n\n  // Starter ALLE uavhengige oppslag SAMTIDIG i stedet for i bølger etter\n  // hverandre (tidligere: maxDate ble ventet HELT ferdig FØR holds-\n  // oppryddingen og åpningstid-oppslaget i det hele tatt startet – tre\n  // separate "bølger" med nettverks-ventetid på HVER ENESTE "hent ledige\n  // tider"-forespørsel, i stedet for to). Alle tre er helt uavhengige av\n  // hverandre; maxDate ventes inn FØRST under (siden den kan gjøre at vi\n  // returnerer tidlig), men de to andre har da allerede vært i gang en\n  // stund i bakgrunnen uansett – bortkastet for den sjeldne "for langt frem\n  // i tid"-dagen, men en reell gevinst for alle andre (de aller fleste)\n  // forespørslene.\n  const maxDatePromise = isFullAdmin ? Promise.resolve(null) : getEffectiveSingleBookingMaxDate();\n  const holdsCleanupPromise = expireStaleHolds().catch((err) => {\n    console.error("[availability] kunne ikke rydde opp utløpte holds:", err);\n  });\n  const hoursPromise = getEffectiveHoursForDate(dateStr);\n\n  if (!isFullAdmin) {\n    // VIKTIG: dette er IKKE det samme som at banen er "stengt" denne dagen\n    // – den er fysisk åpen akkurat som vanlig, det er bare ikke lov å booke\n    // en ENKELTTIME så langt frem i tid (ennå). Får derfor sitt EGET flagg\n    // (`tooFarAhead`) i stedet for å late som dagen er stengt, slik at\n    // bookingsiden kan vise en korrekt melding (se BookingCalendar.tsx).\n    const maxDate = await maxDatePromise;\n    if (maxDate !== null && dateStr > maxDate) {\n      return NextResponse.json({ date: dateStr, slots: [], closed: false, tooFarAhead: true, note: null });\n    }\n  }\n\n  const [hours] = await Promise.all([hoursPromise, holdsCleanupPromise]);\n  if (hours.closed) {\n    return NextResponse.json({ date: dateStr, slots: [], closed: true, note: hours.note });\n  }\n\n  const slots = generateSlotsForDate(dateStr, hours.intervals);', 'const maxDatePromise = isFullAdmin', 'av-parallelize')

CSS_PATH = ROOT / 'app' / 'admin' / 'admin.module.css'
apply_edit(CSS_PATH, '@media (max-width: 820px) {\n  .bcWrap {\n    min-width: 0;\n  }\n\n  .blockStrip .inlineFields > div {', '@media (max-width: 820px) {\n  .bcWrap {\n    min-width: 0;\n    /* "Dagens avtaler" (.agendaPanel) skal ligge ØVERST på mobil, "Oversikt"\n       (kalenderen) under – se .agendaPanel sin order-regel rett under. */\n    order: 2;\n  }\n\n  .agendaPanel {\n    order: 1;\n  }\n\n  .blockStrip .inlineFields > div {', 'order: 1;\n  }\n\n  .blockStrip', 'css-mobile-order')

write_full(ROOT / 'supabase' / 'migrations' / '0005_add_booking_slots_index.sql', '-- Ytelsesfiks: et vanlig B-tre-indeks som faktisk støtter spørringen\n-- findConflictsImpl (lib/db/supabase.ts) kjører på HVERT ENESTE kall til\n-- "hent ledige tider" (court_id = ? AND blocks_time = true AND\n-- start_time < ? AND end_time > ?). EXCLUDE-constraint-en fra\n-- 0001_init.sql bruker GiST og dekker overlapp-operatoren (&&) for å HINDRE\n-- dobbeltbooking, men Postgres kan IKKE bruke den til å svare på denne\n-- spørringen, som sjekker start_time og end_time som to uavhengige\n-- skalar-sammenligninger – uten denne hjelper ingen av de eksisterende\n-- indeksene, og Postgres må lese gjennom HELE booking_slots-tabellen for\n-- hvert eneste kall, noe som har blitt tregere og tregere etter hvert som\n-- historikken har vokst.\ncreate index if not exists booking_slots_conflict_check_idx\n  on booking_slots (court_id, blocks_time, start_time, end_time);\n', 'booking_slots_conflict_check_idx', 'ny fil: supabase/migrations/0005_add_booking_slots_index.sql')

if not ok:
    print("\nEtt eller flere steg feilet - avbryter FOR typecheck (ingenting antas trygt).")
    sys.exit(1)

print("\nKjorer typecheck ...")
result = subprocess.run(["npm", "run", "typecheck"], cwd=ROOT)
if result.returncode == 0:
    print("\nTYPECHECK OK")
    print("\nVIKTIG: Lim innholdet i supabase/migrations/0005_add_booking_slots_index.sql")
    print("inn i Supabase sitt SQL Editor og kjor det der - dette skriptet gjor IKKE det for deg.")
else:
    print("\nTYPECHECK FEILET")
    sys.exit(1)
